package com.example.aymobiledigitallibrary.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.example.aymobiledigitallibrary.data.LibraryRepository;import com.example.aymobiledigitallibrary.model.BrowsingMode;import com.example.aymobiledigitallibrary.ui.components.*
@Composable fun LibraryBrowsingScreen(mode:BrowsingMode,onItemTap:(String)->Unit,onPageClick:(String)->Unit,onFinish:()->Unit){val items=LibraryRepository.items;var page by remember{ mutableIntStateOf(1)};val state=rememberLazyListState();ScreenContainer(scrollable=false){SectionTitle("Library","Browse the materials naturally.");ModeLabel(if(mode==BrowsingMode.CONTINUOUS_LIST)"Continuous List" else "Page View");if(mode==BrowsingMode.CONTINUOUS_LIST){LinearProgressIndicator(progress={(state.firstVisibleItemIndex+1)/30f});LazyColumn(state=state,modifier=Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(12.dp)){items(items){LibraryItemCard(it){onItemTap(it.id)}}}}else{Text("Page $page of 5");LazyColumn(modifier=Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(12.dp)){items(items.filter{it.paginationPage==page}){LibraryItemCard(it){onItemTap(it.id)}}};Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){SecondaryButton("Previous",{page--;onPageClick("prev")},page>1);SecondaryButton("Next",{page++;onPageClick("next")},page<5)}};PrimaryButton("Finish Browsing",onFinish)}}
